// Des: Action map: each Zalo Web action, status and job
// Flo: static tables by category > joined list > print rows and counts (text or JSON)
// I/O: Ctx (caller) > stdout table or JSON; jobs starting with @ are guards or commands, not jobs
// ===================================================================
const std = @import("std"); const ctxz = @import("ct-ctrl-ctxz.zig"); const jobs = @import("ru-jobs-main.zig");
pub const Stat = enum { built, gap, hand, out };
pub const Row = struct { cat: []const u8, act: []const u8, stat: Stat, jobs: []const u8, why: []const u8 };
fn rw(cat: []const u8, act: []const u8, stat: Stat, jobz: []const u8, why: []const u8) Row { return .{ .cat = cat, .act = act, .stat = stat, .jobs = jobz, .why = why }; }
const ACCT = [_]Row{ rw("account", "QR login", .hand, "@cmd:login", "owner scans the QR; za never bypasses"), rw("account", "phone + password login", .hand, "", "za never types secrets"), rw("account", "SMS or verify code", .hand, "@halt", "guard stops; owner types the code"), rw("account", "sign up", .out, "", "Zalo sign-up is mobile-app only"), rw("account", "log out", .built, "logout", ""), rw("account", "logged-in devices list", .built, "devices", ""), rw("account", "remote logout of one device", .built, "devout", ""), rw("account", "profile view", .built, "profile", ""), rw("account", "profile edit (name, avatar, bio)", .gap, "", "live crawl decides if Web allows it"), rw("account", "change password", .hand, "passwd", "opens the page; owner types it"), rw("account", "delete account", .hand, "", "mobile flow; ask-first; never automated"), rw("account", "session expired, log in again", .hand, "@halt", "guard shows the QR page; owner scans"), rw("account", "logged in elsewhere", .hand, "@halt", "guard stops; owner decides") };
const CORE = [_]Row{ rw("core", "read unread chats and history", .built, "read", ""), rw("core", "summary of chats", .built, "summ", ""), rw("core", "search, open by name or phone, label check", .built, "send canary", ""), rw("core", "send text once", .built, "send say", ""), rw("core", "reply recipe and AI draft", .built, "reply", ""), rw("core", "reminders", .built, "remind", ""), rw("core", "quote reply and @mention", .built, "quote", ""), rw("core", "react, recall, delete", .built, "react recall delete", ""), rw("core", "forward", .built, "forward", ""), rw("core", "pin and mute chat", .built, "pin mute", ""), rw("core", "archive, hide, mark unread", .built, "archive hide unread", ""), rw("core", "pin message and download file", .built, "pinmsg download", ""), rw("core", "alias and block", .built, "alias block", ""), rw("core", "unblock", .gap, "", "live crawl: where Web shows the blocked list"), rw("core", "sticker", .built, "sticker", ""), rw("core", "send image, video, file", .built, "file", ""), rw("core", "My Cloud", .built, "cloud", ""), rw("core", "watch loop", .built, "@cmd:watch", ""), rw("core", "voice message", .gap, "", "D15: Web recording unverified"), rw("core", "voice or video call", .out, "", "D16: default out, Web support unclear"), rw("core", "new group", .built, "group", ""), rw("core", "group rename", .built, "rename", ""), rw("core", "group add, remove member, deputy, leave", .built, "addmember delmember deputy leave", ""), rw("core", "group avatar and description", .gap, "", "live crawl decides"), rw("core", "friend request", .built, "friend", ""), rw("core", "friend accept and ignore", .built, "accept ignore", ""), rw("core", "message requests", .built, "reqaccept reqignore", ""), rw("core", "unfriend", .built, "unfriend", ""), rw("core", "poll, note, label", .built, "poll note label", ""), rw("core", "quick messages", .built, "quick usequick", "") };
const DATA = [_]Row{ rw("data", "export own data", .built, "@cmd:export", ""), rw("data", "support report and backup", .built, "@cmd:report @cmd:backup", ""), rw("data", "retry parked item and undo last", .built, "@cmd:retry @cmd:undo", ""), rw("data", "storage view", .built, "storage", ""), rw("data", "usage logs", .built, "@cmd:log", "") };
const MONY = [_]Row{ rw("money", "plans, credits, payment, invoices, cancel", .out, "", "Zalo Web has none; ZaloPay is a separate product"), rw("access", "API keys, team, roles, webhooks, integrations", .out, "", "Zalo Web has none; OA tools are a separate product"), rw("money", "Zalo OA, Shop, Diary, Moments", .out, "", "not on Web per public guides; live crawl confirms") };
const SETT = [_]Row{ rw("settings", "desktop notifications on or off", .built, "notify", ""), rw("settings", "interface language", .built, "lang", ""), rw("settings", "general, theme, shortcuts", .gap, "", "live crawl decides"), rw("settings", "privacy and security pages", .gap, "", "Web may not show them; live crawl decides") };
const HELP = [_]Row{ rw("help", "help page", .built, "help", ""), rw("help", "send feedback", .built, "feedback", ""), rw("help", "about and version", .gap, "", "live crawl decides") };
const EDGE = [_]Row{ rw("edge", "captcha or verify page", .hand, "@halt", "guard waits for the owner, then settles"), rw("edge", "rate limit or action blocked", .built, "@halt", "guard stops everything (unsafe)"), rw("edge", "lock or warning page", .built, "@halt", "guard stops everything (unsafe)"), rw("edge", "benign popups", .built, "@popup", "dismissed; unknown popups stop"), rw("edge", "upload too big", .built, "file", "size cap before upload"), rw("edge", "offline or lost connection", .gap, "", "live crawl: banner text and retry rule"), rw("edge", "unsupported browser or update banner", .hand, "@halt", "guard stops; owner updates Chrome"), rw("edge", "Chrome version change", .built, "canary", "canary prints the version") };
pub const ROWS = ACCT ++ CORE ++ DATA ++ MONY ++ SETT ++ HELP ++ EDGE;
pub fn covered(job: []const u8) bool { for (ROWS) |row| { var itr = std.mem.splitScalar(u8, row.jobs, ' '); while (itr.next()) |tok| { if (std.mem.eql(u8, tok, job)) return true; } } return false; }
pub fn count(stat: Stat) usize { var num: usize = 0; for (ROWS) |row| { if (row.stat == stat) num += 1; } return num; }
pub fn flwsRun(ctx: *ctxz.Ctx) !u8 { if (ctx.args.json) { try ctxz.emit(ctx, try std.json.Stringify.valueAlloc(ctx.allo, ROWS, .{})); try ctxz.emit(ctx, "\n"); return 0; } for (ROWS) |row| { try ctxz.emitf(ctx, "{s: <8} {s: <5} {s}  [{s}] {s}\n", .{ row.cat, @tagName(row.stat), row.act, row.jobs, row.why }); } try ctxz.emitf(ctx, "built {d} · gap {d} · hand {d} · out {d} (built = L1 on the simulator; gap rows wait for the live crawl)\n", .{ count(.built), count(.gap), count(.hand), count(.out) }); _ = jobs.SPECS; return 0; }
